      for(const [id,value] of Object.entries(raw.exercises)){const m=allMissions.find(m=>m.id===id);if(!m||!Array.isArray(value)||value.length!==m.steps.length||value.some(v=>typeof v!=='boolean'))throw Error('Los pasos de una misión no son válidos.');next.exercises[id]=[...value];}
