  let view = 'ruta', toolCategory = 'Todo', toolSearch = '', journalSearch = '', currentDate = null, dateFilters = {type:'Todos',budget:'Todos',place:'Todos'}, simulation = null, pendingImport = null, editingEntry = null;
  const moodLabels = {bien:'Bien',nervios:'Con nervios',ilusion:'Con ilusión',confusion:'Con dudas',bajon:'Un poco abajo',calma:'En calma'};
