  function ring(percent){const offset=100-percent;return `<svg class="progress-ring" viewBox="0 0 40 40" aria-label="${percent}% de la ruta"><circle cx="20" cy="20" r="16"/><circle class="ring-value" cx="20" cy="20" r="16" stroke-dasharray="100.53" stroke-dashoffset="${offset*1.0053}"/></svg>`;}
